(function(){
  const all = Array.isArray(window.ALL_FIXED_COLLOCATIONS) ? window.ALL_FIXED_COLLOCATIONS : [];
  const sourceOrder = ['蓝色森林','四级核心','四级翻译','四级','Word List','短语练习','全方位','听写内容'];
  const children = [{ name:'全部固定搭配', count:all.length, words:all }];
  sourceOrder.forEach((source)=>{ const words=all.filter((w)=>(w.originalSources||[]).includes(source)); if(words.length) children.push({name:source,count:words.length,words}); });
  const patterns=all.filter((w)=>w.fixedKind==='固定句型');
  if(patterns.length) children.push({name:'固定句型',count:patterns.length,words:patterns});
  const folder={name:'固定搭配专项',count:all.length,children};
  const lib=Array.isArray(window.ENGLISH_FOLDER_LIBRARY)?window.ENGLISH_FOLDER_LIBRARY:[];
  window.ENGLISH_FOLDER_LIBRARY=[...lib.filter((x)=>x?.name!=='固定搭配专项'),folder];
})();
